mapper.select:
SELECT p.problem_id as problemId, p.question, p.solutions, p.difficulty, p.source, p.url, p.time_limit as timeLimit, p.memory_limit as memoryLimit, p.input_output as inputOutput, p.expected_aux_space as expectedAuxSpace, p.expected_time_complexity as expectedTimeComplexity FROM problems p
JOIN problem_skills ps ON p.problem_id = ps.problem_id JOIN skills s ON ps.skill_id = s.skill_id
WHERE 1=1
AND p.difficulty = #{difficulty}
AND s.skill_name = #{algorithm}
ORDER BY RAND() LIMIT 1
